const BASE_ASSETS=CATALOG
const NETWORKS=['Tous les réseaux',...new Set(BASE_ASSETS.map(asset=>asset.network))]
const INITIAL = { wallets:[{id:'main',name:'Youg client', balances:Object.fromEntries(BASE_ASSETS.map(a=>[a.id,a.balance]))},DEFAULT_WATCH], defaultWatchAdded:true,active:'main', visible:['usdc','eth'], favorites:['btc','bnb','sol','eth'], history:[], theme:'light', currency:'EUR', notifications:true, hide:false, profile:'Alex Morgan', receiveAddresses:{}, searchRecents:['usdt'], marketPreferences:{tab:'crypto',kind:'Trending',issuer:'bStocks',network:'All networks'} }
const KEY = 'trust-concept-local-v1'
function readData() {
 try {
  const d=JSON.parse(localStorage.getItem(KEY))
  if(d?.wallets?.length&&d.wallets.some(w=>w.id===d.active)){
   const wallets=d.wallets.map(w=>w.id==='main'&&w.name==='Mon portefeuille'?{...w,name:'Youg client'}:w)
   const exists=wallets.some(w=>w.type==='watch'&&w.watch?.network==='ethereum'&&w.watch.address?.toLowerCase()===DEFAULT_WATCH.watch.address.toLowerCase())
   if(!d.defaultWatchAdded&&!exists)wallets.push({...structuredClone(DEFAULT_WATCH),id:wallets.some(w=>w.id===DEFAULT_WATCH.id)?crypto.randomUUID():DEFAULT_WATCH.id})
   return {...INITIAL,...d,wallets,defaultWatchAdded:true}
  }
 }catch{}
 return structuredClone(INITIAL)
}
const digits = n => new Intl.NumberFormat('fr-FR', {maximumFractionDigits:6}).format(n)
const date = d => new Date(d).toLocaleString('fr-FR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})
function Coin({asset,small=false}) { return <span className={`coin ${small?'small':''} ${asset.id}`} style={{background:asset.color}} aria-hidden="true"><AssetIcon asset={asset}/>{asset.id==='usdc'&&<span className="network-dot"><TokenArtwork id="eth"/></span>}</span> }
function BrandLogo() { return <img className="brand-logo" src="/concept-icon.svg" width="447" height="447" alt="Logo Trust Wallet"/> }
function IconButton({icon:Icon,label,onClick,className=''}) { return <button className={`icon-button ${className}`} aria-label={label} onClick={onClick}><Icon/></button> }
function Row({icon:Icon,title,sub,value,onClick,children}) { return <button className="menu-row" onClick={onClick}><span className="menu-leading">{Icon&&<Icon/>}</span><span className="row-text"><strong>{title}</strong>{sub&&<small>{sub}</small>}</span>{children||<><span className="row-value">{value}</span><FiChevronRight className="chevron"/></>}</button> }
function Toggle({checked,onChange,label}) { return <button type="button" className={`toggle ${checked?'on':''}`} role="switch" aria-label={label} aria-checked={checked} onClick={onChange}><span/></button> }

